package com.bank.core;

import java.util.Objects;
import java.util.logging.*;

public class NullSafeCompareDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", null, null); // status & pan null

        // UNSAFE: variable first → NullPointerException when status is null.
        try {
            boolean active = rajesh.getStatus().equals("ACTIVE");
            log.info(() -> "unsafe result → " + active);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "var.equals(literal) threw on null status", e);
        }

        // SAFE: literal first → returns false, no throw.
        boolean activeSafe = "ACTIVE".equals(rajesh.getStatus());
        log.info(() -> "\"ACTIVE\".equals(status) → " + activeSafe);

        // SAFE: both sides possibly null → Objects.equals.
        Account priya = new Account("CUR3001", "ACTIVE", null);
        boolean samePan = Objects.equals(rajesh.getPanId(), priya.getPanId());
        log.info(() -> "Objects.equals(null, null) for PAN → " + samePan);

        Account withPan = new Account("CUR3001", "ACTIVE", "ABCDE1234F");
        boolean samePan2 = Objects.equals(rajesh.getPanId(), withPan.getPanId());
        log.info(() -> "Objects.equals(null, \"ABCDE1234F\") → " + samePan2);
    }
}
